from pathlib import Path
import base64, mimetypes
root=Path.home()/"workspace/your_files/phantom-of-larose-attribution-package"
media=root/'.src/media'
def data(name):
 p=media/name
 return 'data:'+mimetypes.guess_type(p.name)[0]+';base64,'+base64.b64encode(p.read_bytes()).decode()
imgs={p.name:data(p.name) for p in media.glob('*.jpg')}
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Phantom of LaRose - Provisional Attribution Package</title><style>
@page{size:Letter;margin:0}*{box-sizing:border-box;print-color-adjust:exact;-webkit-print-color-adjust:exact}body{margin:0;background:#ddd;font-family:'Liberation Sans','Noto Sans',sans-serif;color:#191919}.page{width:8.5in;min-height:11in;height:11in;padding:.55in .62in .48in;background:#fff;position:relative;page-break-after:always;overflow:hidden}.page:last-child{page-break-after:auto}h1,h2,h3,p,ul,ol{margin-top:0}h1{font-family:'Noto Serif','Liberation Serif',serif;font-size:29pt;line-height:1.05;margin-bottom:.16in;color:#161616}h2{font-family:'Noto Serif','Liberation Serif',serif;font-size:19pt;margin-bottom:.18in;padding-bottom:.08in;border-bottom:2px solid #8b1e24}h3{font-size:11.5pt;text-transform:uppercase;letter-spacing:.05em;color:#8b1e24;margin:.18in 0 .08in}p,li{font-size:10.3pt;line-height:1.42}.lead{font-size:13pt;line-height:1.45}.muted{color:#5f5f5f}.small{font-size:8.5pt;line-height:1.35}.kicker{font-size:9pt;letter-spacing:.13em;text-transform:uppercase;color:#8b1e24;font-weight:bold}.rule{height:4px;background:#8b1e24;margin:.22in 0}.hero{display:grid;grid-template-columns:1.25fr .75fr;gap:.32in;align-items:center;margin:.35in 0}.hero img{width:100%;height:4.15in;object-fit:contain;background:#eee}.summary{border-left:5px solid #8b1e24;background:#f5f1ec;padding:.18in .22in}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:.18in}.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:.14in}.card{break-inside:avoid;border:1px solid #cac4bc;padding:.14in;background:#fff}.card h3{margin-top:0}.card p:last-child,.card ul:last-child{margin-bottom:0}.photo{margin:0;border:1px solid #bbb;background:#f4f4f4;padding:.06in;break-inside:avoid}.photo img{width:100%;height:2.3in;object-fit:contain;background:#111}.photo.tall img{height:3.1in}.photo.wide img{height:2.0in}.photo figcaption{font-size:8.2pt;line-height:1.3;padding:.06in .04in .02in}.note{background:#f6f2ed;border:1px solid #d3c6b9;padding:.15in .18in;margin:.14in 0}.warning{background:#fbf1ef;border-left:5px solid #8b1e24;padding:.14in .18in;margin:.14in 0}.facts{display:grid;grid-template-columns:1fr 1fr;gap:.12in .2in}.fact{border-top:1px solid #bbb;padding-top:.07in}.fact b{display:block;font-size:8.2pt;color:#666;text-transform:uppercase;letter-spacing:.05em;margin-bottom:.03in}.steps{counter-reset:s}.step{position:relative;padding-left:.46in;margin:.15in 0;min-height:.34in}.step:before{content:attr(data-n);position:absolute;left:0;top:-.01in;width:.31in;height:.31in;border-radius:50%;background:#8b1e24;color:#fff;text-align:center;line-height:.31in;font-weight:bold}.checklist{columns:2;column-gap:.35in}.checklist li{break-inside:avoid;margin-bottom:.09in}.status{display:inline-block;padding:.03in .07in;border-radius:10px;font-size:8pt;font-weight:bold}.have{background:#e1eee5;color:#225c35}.need{background:#f5ded8;color:#7b2424}table{width:100%;border-collapse:collapse;font-size:9pt;break-inside:avoid}th{text-align:left;background:#292929;color:#fff;padding:.07in}td{border-bottom:1px solid #ccc;padding:.07in;vertical-align:top}.footer{position:absolute;left:.62in;right:.62in;bottom:.2in;border-top:1px solid #aaa;padding-top:.06in;font-size:8pt;color:#666;display:flex;justify-content:space-between}.sources li{font-size:8.7pt;margin-bottom:.11in;word-break:break-word}a{color:#8b1e24;text-decoration:none}.tight li{margin-bottom:.04in}.sig{display:grid;grid-template-columns:1fr 1fr;gap:.25in;margin-top:.25in}.line{border-bottom:1px solid #333;height:.3in}.captionbar{font-size:8.5pt;background:#292929;color:#fff;padding:.08in .1in}.coverlabel{font-size:9pt;background:#8b1e24;color:#fff;padding:.06in .1in;display:inline-block;text-transform:uppercase;letter-spacing:.08em;font-weight:bold}
</style></head><body>'''
def page(body,num,title='Phantom of LaRose - Provisional Attribution Package'):
 return f'<section class="page">{body}<div class="footer"><span>{title}</span><span>{num}</span></div></section>'
html+=page(f'''<span class="coverlabel">Working submission dossier</span><div class="hero"><div><div class="kicker">2026 Mayflower Compact quarter</div><h1>Phantom of LaRose</h1><p class="lead">Provisional die-marker and progression record for expert examination</p><div class="rule"></div><p class="muted">Prepared from ten supplied microscope images and the collector's public “Death of a Die” documentation.</p></div><img src="{imgs['2026-09-13_phantom-larose-003_hand-detail-multi-arrows.jpg']}" alt="Annotated microscope view of the clasped hands area on a 2026 Mayflower Compact quarter"></div><div class="summary"><h3>Executive assessment</h3><p>The record shows a coherent group of small, location-specific features near the clasped hands. The images are sufficient to request an expert opinion. They are <b>not yet sufficient to claim a recognized variety</b>: the mint, specimen count, full-coin views, and repeatability across separate coins have not been documented in the supplied files.</p></div><div class="grid2" style="margin-top:.2in"><div class="card"><h3>Current strengths</h3><ul class="tight"><li>Named diagnostic locations</li><li>Annotated and unannotated close-ups</li><li>Four timestamped contextual views</li><li>Public progression narrative</li></ul></div><div class="card"><h3>Highest-value next step</h3><p>Photograph one candidate coin front and back, record its mint and acquisition source, then show the same three markers on a second coin if available.</p></div></div>''',1)
html+=page('''<div class="kicker">Specimen record</div><h2>The host coin is identified; the individual specimen is not</h2><p>The United States Mint identifies this one-year design as the 2026 Mayflower Compact quarter. Its obverse shows two Pilgrims embracing; its reverse shows the <i>Mayflower</i> under full sail. The current photographs concentrate on the clasped-hands area and do not preserve the full identity of any single coin.</p><div class="facts"><div class="fact"><b>Denomination</b>Quarter dollar (25 cents)</div><div class="fact"><b>Program</b>2026 Semiquincentennial</div><div class="fact"><b>Design</b>Mayflower Compact</div><div class="fact"><b>Mint</b>Not recorded in supplied files</div><div class="fact"><b>Specimen count</b>Not established</div><div class="fact"><b>Acquisition source</b>Not recorded</div><div class="fact"><b>Weight / diameter</b>Not recorded</div><div class="fact"><b>Orientation</b>Clasped-hands region documented</div></div><div class="warning"><b>Do not submit this as a confirmed new variety.</b> Submit it as a request to determine whether the marks represent a repeatable die variety, ordinary die deterioration, strike doubling, contact damage, or another cause.</div><h3>Minimum identity record to add</h3><ul class="checklist"><li>Uncropped obverse photograph</li><li>Uncropped reverse photograph</li><li>Edge photograph</li><li>Mint identification</li><li>Weight to 0.01 gram</li><li>Diameter to 0.1 millimeter</li><li>Date and place found</li><li>One specimen number per coin</li><li>Same lighting for comparisons</li><li>Images before annotation</li></ul><div class="note"><b>Naming note:</b> This package preserves the collector's labels exactly as pictured: “Mosquito Bite,” “Splenter,” and “Ant Bite.” “Splenter” should be confirmed before public submission if “Splinter” was intended.</div>''',2)
html+=page(f'''<div class="kicker">Primary diagnostics</div><h2>Three features near the hands form the working marker set</h2><div class="grid3"><figure class="photo tall"><img src="{imgs['2026-09-13_phantom-larose-001_hand-closeup-arrows.jpg']}" alt="Annotated close-up of small features near the clasped hands"><figcaption><b>View A.</b> Two red arrows indicate features along and below the hand.</figcaption></figure><figure class="photo tall"><img src="{imgs['2026-09-13_phantom-larose-002_die-chip-arrows.jpg']}" alt="Annotated extreme close-up of line-like features near the hand"><figcaption><b>View B.</b> Three arrows isolate line-like or raised-looking features.</figcaption></figure><figure class="photo tall"><img src="{imgs['2026-09-13_phantom-larose-004_die1-markers-reference.jpg']}" alt="Reference screenshot naming the Die 1 markers"><figcaption><b>Reference label.</b> The supplied image names the three “Die-1 Markers.”</figcaption></figure></div><div class="grid3" style="margin-top:.18in"><div class="card"><h3>Mosquito Bite</h3><p>Collector label for a small localized point feature. Exact relief and coordinates need an unannotated macro image.</p></div><div class="card"><h3>Splenter</h3><p>Collector label for a thin line or chip-like feature. Spelling and morphology should be confirmed.</p></div><div class="card"><h3>Ant Bite</h3><p>Collector label for another small point feature. Incuse versus raised relief is not resolved here.</p></div></div><div class="warning"><b>Key diagnostic test:</b> a true die marker should recur in the same location, shape, and orientation on more than one coin struck from the same die.</div>''',3)
html+=page(f'''<div class="kicker">Context images</div><h2>Timestamped wide views preserve orientation around the design</h2><div class="grid2"><figure class="photo wide"><img src="{imgs['2025-04-10_phantom-larose-007_wide-231851.jpg']}" alt="Wide microscope view of clasped hands area timestamped 23:18:51"><figcaption><b>Context 01 - 23:18:51.</b> Hands, surrounding field, and nearby inscription detail.</figcaption></figure><figure class="photo wide"><img src="{imgs['2025-04-10_phantom-larose-008_wide-231848.jpg']}" alt="Wide microscope view of lower arm area timestamped 23:18:48"><figcaption><b>Context 02 - 23:18:48.</b> Adjacent arm and field at a similar scale.</figcaption></figure><figure class="photo wide"><img src="{imgs['2025-04-10_phantom-larose-009_wide-141509.jpg']}" alt="Wide microscope view of opposite side hand detail timestamped 14:15:09"><figcaption><b>Context 03 - 14:15:09.</b> Second hand area and nearby inscription detail.</figcaption></figure><figure class="photo wide"><img src="{imgs['2025-04-10_phantom-larose-010_wide-141456.jpg']}" alt="Wide microscope view of opposite side hand detail timestamped 14:14:56"><figcaption><b>Context 04 - 14:14:56.</b> Companion view taken thirteen seconds earlier.</figcaption></figure></div><div class="note"><b>Chronology caution:</b> these images display “2025/04/10,” which predates the 2026 coin date. That may reflect an incorrect microscope clock. Confirm the true capture date before using the timestamp as evidence of progression.</div><p class="small muted">For formal comparison, add a small locator box on a full-coin image showing exactly where each context frame sits. Keep the original files unchanged and create separate annotated copies.</p>''',4)
html+=page(f'''<div class="kicker">Supplemental observations</div><h2>Line-like and dot-like features deserve separate testing</h2><div class="grid3"><figure class="photo tall"><img src="{imgs['2026-09-13_phantom-larose-003_hand-detail-multi-arrows.jpg']}" alt="Annotated hand detail with multiple arrows and boundary marks"><figcaption><b>Multi-feature map.</b> Useful as a locator, but dense annotation obscures some surfaces.</figcaption></figure><figure class="photo tall"><img src="{imgs['2026-09-13_phantom-larose-005_doubling-red-lines.jpg']}" alt="Close-up with red lines marking possible doubling"><figcaption><b>Possible doubling.</b> The image marks a separation along a design edge; cause is unconfirmed.</figcaption></figure><figure class="photo tall"><img src="{imgs['2026-09-13_phantom-larose-006_closeup-dots.jpg']}" alt="Unannotated close-up showing small bright points near fingers"><figcaption><b>Point features.</b> An unannotated view preserves surface texture and lighting response.</figcaption></figure></div><h3>Working hypotheses to test</h3><div class="grid2"><div class="card"><h3>Die-origin possibilities</h3><ul class="tight"><li>Small die chip or break</li><li>Die crack or retained fragment</li><li>Die clash transfer</li><li>Progressive die deterioration</li></ul></div><div class="card"><h3>Non-variety possibilities</h3><ul class="tight"><li>Contact or circulation damage</li><li>Lighting or focus artifact</li><li>Machine/strike doubling</li><li>Plating or surface disturbance</li></ul></div></div><p class="small muted" style="margin-top:.15in">Relief direction matters. Tilt lighting from four directions and record whether each feature remains visibly raised or incuse. Do not sharpen or enhance the submission images beyond basic exposure and white-balance correction.</p>''',5)
html+=page('''<div class="kicker">Interpretation</div><h2>The evidence supports examination, not market claims</h2><div class="summary"><p class="lead"><b>Best current conclusion:</b> this is a documented candidate die-marker group with a plausible progression story. Independent attribution has not been established.</p></div><h3>Reasonable statements now</h3><ul><li>The photographs show multiple small features clustered near a consistent design area.</li><li>The collector has assigned provisional names to three markers and assembled comparative views.</li><li>A public “Death of a Die” reel records a broader progression narrative, including the “Scare Face” label.</li><li>An expert can use this package to request better evidence or a physical examination.</li></ul><h3>Statements to avoid until confirmed</h3><ul><li>“New recognized variety,” “unique,” “rare,” or a dollar-value claim.</li><li>Calling every line a doubled die, clash, crack, or break without diagnostics.</li><li>Claiming chronological progression from camera timestamps that may be incorrect.</li><li>Assuming multiple photographs represent multiple coins.</li></ul><div class="warning"><b>Market reality:</b> third-party grading services may decline to attribute insignificant chips, breaks, cracks, normal die wear, strike doubling, or die deterioration. Recognition depends on the feature class, repeatability, significance, and the catalog's policies.</div><p class="small muted">A strong negative opinion is still useful: it clarifies the correct classification and prevents unsupported sales claims.</p>''',6)
html+=page('''<div class="kicker">Submission plan</div><h2>Seven steps turn the archive into an attribution request</h2><div class="step" data-n="1"><p><b>Assign specimen IDs.</b> Label each physical coin PL-01, PL-02, and so on. Never mix photographs from different coins without saying so.</p></div><div class="step" data-n="2"><p><b>Photograph the whole coin.</b> Capture obverse, reverse, and edge before macro work. Include a ruler or scale image separately.</p></div><div class="step" data-n="3"><p><b>Re-shoot the markers.</b> Make one unannotated image and one annotated copy for each marker. Keep magnification and lighting consistent.</p></div><div class="step" data-n="4"><p><b>Prove repeatability.</b> Show the same marker configuration on at least two independently found coins if available.</p></div><div class="step" data-n="5"><p><b>Build a chronology.</b> Record acquisition and photography dates outside the image. Treat embedded microscope dates as unverified until checked.</p></div><div class="step" data-n="6"><p><b>Post to the CONECA forum.</b> Create an account, open a new-attribution thread, and attach the concise evidence set. Do not mail a coin until an assigned attributor provides instructions.</p></div><div class="step" data-n="7"><p><b>Publish carefully.</b> Share the process and ask for comparison specimens. Describe the name as provisional until an attribution number is issued.</p></div><div class="note"><b>CONECA process:</b> membership is not required, but a forum ID is. The public service page lists attribution at $8 per coin for members and $10 for non-members, plus return postage and insurance. Confirm current fees before sending.</div><h3>Draft forum subject</h3><p class="lead">2026 Mayflower Compact quarter - request for review of repeatable clasped-hands markers (“Phantom of LaRose,” provisional)</p>''',7)
html+=page('''<div class="kicker">Draft cover note - use after adding the missing evidence</div><h2>A concise request keeps the examiner focused on the evidence</h2><div class="card" style="padding:.28in"><p>Hello,</p><p>I am requesting an expert opinion on a possible die-marker group on a 2026 Mayflower Compact quarter. My provisional project name is “Phantom of LaRose.” The three working marker labels are “Mosquito Bite,” “Splenter,” and “Ant Bite,” all located near the clasped-hands design area.</p><p>I have attached full-coin photographs, unannotated macro photographs, annotated locator copies, and comparison images. I am asking whether these features are consistent with a repeatable die variety, ordinary die deterioration, strike doubling, post-mint damage, or another cause.</p><p>I am not representing this as an attributed variety. If a physical examination is needed, please provide the correct shipping instructions and current fee.</p><p>Thank you for your review.</p><div class="sig"><div><div class="line"></div><p class="small">Name</p></div><div><div class="line"></div><p class="small">Forum username</p></div></div><div class="sig"><div><div class="line"></div><p class="small">Email or preferred contact</p></div><div><div class="line"></div><p class="small">Date</p></div></div></div><h3>Attach only the strongest evidence</h3><ul class="checklist"><li>Full obverse and reverse</li><li>Three unannotated macros</li><li>Three annotated copies</li><li>Two-coin comparison, if available</li><li>Specimen data sheet</li><li>This concise cover note</li></ul><div class="warning"><b>Before posting:</b> replace every missing specimen field. The current packet intentionally leaves unknowns unresolved rather than guessing.</div>''',8)
rows=''.join(f'<tr><td>{i+1:02d}</td><td>{n.replace("_"," ")}</td><td>{d}</td></tr>' for i,(n,d) in enumerate([
('2026-09-13 ... 001','Annotated hand close-up'),('2026-09-13 ... 002','Annotated line/chip close-up'),('2026-09-13 ... 003','Multi-marker map'),('2026-09-13 ... 004','Marker-name reference'),('2026-09-13 ... 005','Possible doubling lines'),('2026-09-13 ... 006','Unannotated point features'),('2025-04-10 ... 007','Wide view, 23:18:51'),('2025-04-10 ... 008','Wide view, 23:18:48'),('2025-04-10 ... 009','Wide view, 14:15:09'),('2025-04-10 ... 010','Wide view, 14:14:56')]))
html+=page(f'''<div class="kicker">Appendix</div><h2>The evidence index preserves the supplied record</h2><table><thead><tr><th>No.</th><th>File</th><th>Role in package</th></tr></thead><tbody>{rows}</tbody></table><h3>Public sources</h3><ol class="sources"><li><b>United States Mint.</b> 2026 Semiquincentennial Rolls and Bags - Mayflower Compact. <a href="https://www.usmint.gov/semiquincentennial-quarters-2026-rolls-and-bags-mayflower-compact-MASTER_SEMIQMC.html">usmint.gov/.../MASTER_SEMIQMC.html</a></li><li><b>CONECA.</b> Attribution Services. Forum-first submission process, fees, and assignment procedure. <a href="https://conecaonline.org/attribution-services/">conecaonline.org/attribution-services/</a></li><li><b>NGC / Mint Error News archive.</b> Public description of categories commonly excluded from variety attribution. <a href="https://minterrornews.com/features-11-8-10-variety_vs_mint_error.html">minterrornews.com/features-11-8-10-variety_vs_mint_error.html</a></li><li><b>Collector's Facebook reel.</b> “Death of a Die” / “Phantom of Larose” progression record, posted May 18, 2026. <a href="https://www.facebook.com/reel/1663173261566217/">facebook.com/reel/1663173261566217/</a></li></ol><div class="note"><b>Evidence status:</b> The ten images in this packet are the complete photographic set currently on file. No physical coin examination, scale calibration, metadata verification, or independent attribution was performed.</div>''',9)
html+='</body></html>'
(root/'.src/index.html').write_text(html)
